import {build} from 'esbuild';
import fs from 'node:fs/promises';
await build({entryPoints:['src/main.js'],bundle:true,outfile:'app.js',format:'iife',target:'es2020',minify:true,legalComments:'eof'});
const html=await fs.readFile('index.html','utf8'),js=await fs.readFile('app.js','utf8');
await fs.writeFile('AVATARES-AURA-DEMO.html',html.replace('<script src="app.js"></script>',()=>'<script>'+js.replaceAll('</script','<\\/script')+'</script>'));
console.log('Built offline avatar studio.');

await build({entryPoints:['src/embed.js'],bundle:true,outfile:'integration/embed.bundle.js',format:'iife',target:'es2020',minify:true,legalComments:'eof'});
const embed=await fs.readFile('integration/embed.bundle.js','utf8');const map={};
for(const id of ['antonio','claudio','aura']){const html='<!doctype html><html><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1"><style>html,body,#avatar{margin:0;width:100%;height:100%;overflow:hidden;background:transparent}canvas{display:block;touch-action:none}</style><body data-avatar="'+id+'"><div id="avatar"></div><script>'+embed.replaceAll('</script','<\\/script')+'</script></body></html>';map[id]=html;await fs.writeFile('integration/'+id+'-embed.html',html);}
await fs.writeFile('integration/avatarHtml.ts','// Generated by tools/build.mjs. Offline, no external requests.\nexport const AVATAR_HTML = '+JSON.stringify(map)+' as const;\n');
